/* ---------------- Ghi chú đơn ---------------- */
function NoteModal({ b, onClose, onAdd, onResolve }) {
  const [t, setT] = useState('');
  return <Modal title={`Ghi chú — ${b.code}`} onClose={onClose}><div className="space-y-3">
    <div className="max-h-64 overflow-auto space-y-2">{b.notes.map((n, i) => ({ n, i })).sort((a, c) => !!a.n.done - !!c.n.done || c.i - a.i).map(({ n, i }) => <div key={i} className={`rounded-lg border px-3 py-2 text-sm ${n.done ? 'bg-slate-50 opacity-70' : 'bg-amber-50/50'}`}><div className="text-ink break-words whitespace-pre-wrap">{n.t}</div><div className="text-xs text-slate-400 mt-1">{n.by} · {n.at}</div>{n.done ? <div className="text-xs text-emerald-700 mt-1">✓ Đã xử lý bởi {n.done.by} · {n.done.at}</div> : <button type="button" className="mt-2 h-8 px-3 rounded-lg border bg-white text-xs font-semibold hover:bg-slate-50" onClick={() => onResolve(i)}>Xác nhận đã xử lý</button>}</div>)}{!b.notes.length && <p className="text-sm text-slate-400">Chưa có ghi chú.</p>}</div>
    <textarea rows={3} className="field" placeholder="Nhập ghi chú cho đơn này..." value={t} onChange={e => setT(e.target.value)} /><Btn disabled={!t.trim()} onClick={() => { onAdd(t.trim()); setT(''); }}>Thêm ghi chú</Btn></div></Modal>;
}

const SVC = [['Giặt ủi', 50000], ['Ăn sáng', 120000], ['Minibar', 80000], ['Đưa đón sân bay', 300000], ['Thuê xe máy', 150000]];
